double sensible_cp_deltaT(double A, double B, double C,
                           double D, double E,
                           double T, double Tref)
{
    double t     = T / 1000.0;
    double tref  = Tref / 1000.0;

    double delta_H =
        1000.0 * (
            A * (t - tref)
            + (B / 2.0) * (t*t - tref*tref)
            + (C / 3.0) * (t*t*t - tref*tref*tref)
            + (D / 4.0) * (t*t*t*t - tref*tref*tref*tref)
            - E * (1.0/t - 1.0/tref)
        );

    return delta_H;
}

real diffusion_O2_fuller(real T, real P_Pa)
{
    // ---- Konstanten ---- //
    real M_o2   = 32.0;      // g/mol //
    real M_air  = 28.97;     // g/mol //

    real V_O2   = 16.6;
    real V_air  = 20.1;

    // ---- Druck in atm umrechnen ---- //
    real P_atm = P_Pa / 101325.0;

    // ---- Fuller Gleichung (cm2/s) ---- //
    real numerator = 0.001 * pow(T,1.75)
                     * sqrt(1.0/M_o2 + 1.0/M_air);

    real denom = P_atm *
                 pow( pow(V_O2,1.0/3.0)
                    + pow(V_air,1.0/3.0), 2.0);

    real D_cm2_s = numerator / denom;

    // ---- Umrechnung nach m2/s ---- //
    return D_cm2_s * 1e-4;
}

